11	// FusedAddRmsnorm op_host — tiling calculation + strategy dispatch + EXEC_KERNEL_CMD launch
12	
13	#include <algorithm>
14	#include <cstdint>
15	
16	#include <torch/extension.h>
17	#include <torch/library.h>
18	
19	#include "torch_kernel_helper.h"
20	#include "tiling/platform/platform_ascendc.h"
21	
22	#include "aclrtlaunch_fused_add_rmsnorm_merge_n.h"
23	#include "aclrtlaunch_fused_add_rmsnorm_single_row.h"
24	#include "aclrtlaunch_fused_add_rmsnorm_splitd.h"
25	
26	// ---------------------------------------------------------------------------
27	// Tiling constants
28	// ---------------------------------------------------------------------------
29	
30	constexpr int32_t DEFAULT_BLOCK_M = 64;
31	constexpr int32_t DEFAULT_ROW_FACTOR = 8;
32	constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
33	
34	// ---------------------------------------------------------------------------
35	// Host function
36	// ---------------------------------------------------------------------------
37	
38	namespace ascend_kernel {
39	
40	at::Tensor fused_add_rmsnorm(
41	    const at::Tensor &hidden_states,
42	    const at::Tensor &residual,
43	    const at::Tensor &weight,
44	    double eps)
45	{
46	    TORCH_CHECK(hidden_states.dim() == 2, "hidden_states must be [M, N]");
47	    TORCH_CHECK(residual.dim() == 2, "residual must be [M, N]");
48	    TORCH_CHECK(weight.dim() == 1, "weight must be [N]");
49	    TORCH_CHECK(
50	        hidden_states.scalar_type() == at::kFloat || hidden_states.scalar_type() == at::kHalf ||
51	            hidden_states.scalar_type() == at::kBFloat16,
52	        "hidden_states must be float16, float32, or bfloat16");
53	    TORCH_CHECK(residual.scalar_type() == hidden_states.scalar_type(),
54	        "residual must have the same dtype as hidden_states");
55	    TORCH_CHECK(weight.scalar_type() == hidden_states.scalar_type(),
56	        "weight must have the same dtype as hidden_states");
57	    TORCH_CHECK(hidden_states.is_contiguous(), "hidden_states must be contiguous");
58	    TORCH_CHECK(residual.is_contiguous(), "residual must be contiguous");
59	    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
60	    TORCH_CHECK(
61	        static_cast<int32_t>(hidden_states.sizes()[1]) == static_cast<int32_t>(residual.sizes()[1]),
62	        "hidden_states and residual must have same N");
63	    TORCH_CHECK(
64	        static_cast<int32_t>(hidden_states.sizes()[0]) == static_cast<int32_t>(residual.sizes()[0]),
65	        "hidden_states and residual must have same M");
66	    TORCH_CHECK(
67	        static_cast<int32_t>(hidden_states.sizes()[1]) == static_cast<int32_t>(weight.sizes()[0]),
68	        "weight shape mismatch");
69	
70	    int32_t M = static_cast<int32_t>(hidden_states.sizes()[0]);
71	    int32_t N = static_cast<int32_t>(hidden_states.sizes()[1]);
72	
73	    int32_t mNum = (M + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
74	    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, mNum));
75	    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;
76	
77	    at::Tensor y = at::empty_like(hidden_states);
78	
79	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
80	    int64_t dtypeFlag = 0;
81	    if (hidden_states.scalar_type() == at::kHalf) {
82	        dtypeFlag = 1;
83	    } else if (hidden_states.scalar_type() == at::kBFloat16) {
84	        dtypeFlag = 2;
85	    }
86	
87	    // All tiling params as left values (required by EXEC_KERNEL_CMD)
88	    int32_t blockM = DEFAULT_BLOCK_M;
89	    int32_t rowFactor = DEFAULT_ROW_FACTOR;
90	    float epsVal = static_cast<float>(eps);
91	    float invN = 1.0f / static_cast<float>(N);
92	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
93	
94	    // Strategy dispatch: select kernel based on N size
95	    if (N <= 1024) {
96	        EXEC_KERNEL_CMD(fused_add_rmsnorm_merge_n, blockDim,
97	                        hidden_states, residual, weight, y,
98	                        M, N, blockM, usedCoreNum, tasksPerCore, rowFactor, epsVal, invN,
99	                        dtypeFlag);
100	    } else if (N > 8192) {
101	        EXEC_KERNEL_CMD(fused_add_rmsnorm_splitd, blockDim,
102	                        hidden_states, residual, weight, y,
103	                        M, N, blockM, usedCoreNum, tasksPerCore, epsVal, invN,
104	                        dtypeFlag);
105	    } else {
106	        EXEC_KERNEL_CMD(fused_add_rmsnorm_single_row, blockDim,
107	                        hidden_states, residual, weight, y,
108	                        M, N, blockM, usedCoreNum, tasksPerCore, epsVal, invN,
109	                        dtypeFlag);
110	    }
111	
112	    return y;
113	}
114	
115	}  // namespace ascend_kernel
