110	// =========================================================================
111	// Base class for SingleRow and SplitD strategies — shared Init and members
112	// =========================================================================
113	
114	template <typename dataType>
115	class FusedAddRmsnormKernelBase {
116	public:
117	    __aicore__ inline void InitBase(
118	        GM_ADDR hiddenStates, GM_ADDR residual, GM_ADDR weight, GM_ADDR y,
119	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
120	        int32_t tasksPerCore, float eps, float invN)
121	    {
122	        this->M = M;
123	        this->N = N;
124	        this->blockM = blockM;
125	        this->usedCoreNum = usedCoreNum;
126	        this->tasksPerCore = tasksPerCore;
127	        this->eps = eps;
128	        this->invN = invN;
129	
130	        hsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(hiddenStates), static_cast<uint64_t>(M) * N);
131	        resGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(residual), static_cast<uint64_t>(M) * N);
132	        weightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(weight), N);
133	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
134	    }
135	
136	protected:
137	    int32_t M = 0;
138	    int32_t N = 0;
139	    int32_t blockM = 0;
140	    int32_t usedCoreNum = 0;
141	    int32_t tasksPerCore = 0;
142	    float eps = 0.0f;
143	    float invN = 0.0f;
144	    int subBlockRows_ = 0;
145	
146	    AscendC::TPipe pipe;
147	    AscendC::GlobalTensor<dataType> hsGM_;
148	    AscendC::GlobalTensor<dataType> resGM_;
149	    AscendC::GlobalTensor<dataType> weightGM_;
150	    AscendC::GlobalTensor<dataType> yGM_;
151	};
152	
153	// =========================================================================
154	// Strategy 1: merge_n — preferred when N <= 1024
155	// =========================================================================
156	
157	template <typename dataType>
158	class FusedAddRmsnormMergeNKernel {
159	public:
160	    __aicore__ inline void Init(
161	        GM_ADDR hiddenStates, GM_ADDR residual, GM_ADDR weight, GM_ADDR y,
162	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
163	        int32_t tasksPerCore, int32_t rowFactor, float eps, float invN)
164	    {
165	        this->M = M;
166	        this->N = N;
167	        this->blockM = blockM;
168	        this->usedCoreNum = usedCoreNum;
169	        this->tasksPerCore = tasksPerCore;
170	        this->rowFactor = rowFactor;
171	        this->eps = eps;
172	        this->invN = invN;
173	
174	        hsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(hiddenStates), static_cast<uint64_t>(M) * N);
175	        resGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(residual), static_cast<uint64_t>(M) * N);
176	        weightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(weight), N);
177	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
178	
179	        if ASCEND_IS_AIV { InitAivBuffers(); }
180	    }
181	
182	    __aicore__ inline void InitAivBuffers()
183	    {
184	        subBlockRows_ = blockM / AscendC::GetSubBlockNum();
185	        rowLoops_ = subBlockRows_ / rowFactor;
186	        pipe.InitBuffer(weightBuf_, N * sizeof(dataType));
187	        pipe.InitBuffer(hsInQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
188	        pipe.InitBuffer(resInQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
189	        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
190	        pipe.InitBuffer(xBuf_, kMergeRowFactor * N * sizeof(float));
191	        pipe.InitBuffer(scaleBuf_, kMergeRowFactor * N * sizeof(float));
192	        pipe.InitBuffer(weightTileBuf_, kMergeRowFactor * N * sizeof(float));
193	        pipe.InitBuffer(weightBroadcastTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
194	        pipe.InitBuffer(scaleBroadcastTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
195	        pipe.InitBuffer(reduceBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
196	        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
197	        pipe.InitBuffer(invRmsBuf_, kMergeRowFactor * sizeof(float));
198	        if constexpr (!std::is_same_v<dataType, float>) {
199	            pipe.InitBuffer(hsCastBuf_, kMergeRowFactor * N * sizeof(float));
200	            pipe.InitBuffer(resCastBuf_, kMergeRowFactor * N * sizeof(float));
201	            pipe.InitBuffer(weightCastBuf_, N * sizeof(float));
202	            pipe.InitBuffer(yCastBuf_, kMergeRowFactor * N * sizeof(float));
203	        }
204	
205	        const uint32_t weightSrcShape[2] = {1U, static_cast<uint32_t>(N)};
206	        const uint32_t weightDstShape[2] = {
207	            static_cast<uint32_t>(kMergeRowFactor),
208	            static_cast<uint32_t>(N),
209	        };
210	
211	        // Load and broadcast weight once
212	        weightInLocal_ = weightBuf_.Get<dataType>();
213	        LoadGmToUb(weightInLocal_, weightGM_, static_cast<uint32_t>(N));
214	        AscendC::PipeBarrier<PIPE_MTE2>();
215	        AscendC::PipeBarrier<PIPE_ALL>();
216	        PrepareInputTensor(weightLocal_, weightInLocal_, weightCastBuf_, N);
217	
218	        weightTileLocal_ = weightTileBuf_.Get<float>();
219	        weightBroadcastTmpLocal_ = weightBroadcastTmpBuf_.Get<uint8_t>();
220	        AscendC::PipeBarrier<PIPE_ALL>();
221	        AscendC::Broadcast<float, 2, 0>(
222	            weightTileLocal_,
223	            weightLocal_,
224	            weightDstShape,
225	            weightSrcShape,
226	            weightBroadcastTmpLocal_);
227	        AscendC::PipeBarrier<PIPE_V>();
228	    }
229	
230	    __aicore__ inline void Process()
231	    {
232	        if ASCEND_IS_AIV {
233	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
234	            const int subBlockIdx = AscendC::GetSubBlockIdx();
235	
236	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
237	                const int bx = coreIdx * tasksPerCore + localIdx;
238	                if (bx >= BlockCountHelper(M, blockM)) {
239	                    continue;
240	                }
241	
242	                for (int r = 0; r < rowLoops_; ++r) {
243	                    const int rowBase = bx * blockM + subBlockIdx * subBlockRows_ + r * rowFactor;
244	                    const int validRows = M - rowBase;
245	                    if (validRows > 0) {
246	                        ProcessRows(rowBase, validRows >= kMergeRowFactor ? kMergeRowFactor : validRows);
247	                    }
248	                }
249	            }
250	        }
251	    }
252	
253	private:
254	    static constexpr int kMergeRowFactor = 8;
255	
256	    __aicore__ inline void CopyInHs(int32_t rowBase, int32_t count)
257	    {
258	        hsInLocal_ = hsInQueue_.AllocTensor<dataType>();
259	        LoadGmToUb(hsInLocal_, hsGM_[static_cast<uint64_t>(rowBase) * N], static_cast<uint32_t>(count));
260	        hsInQueue_.EnQue(hsInLocal_);
261	    }
262	
263	    __aicore__ inline void CopyInRes(int32_t rowBase, int32_t count)
264	    {
265	        resInLocal_ = resInQueue_.AllocTensor<dataType>();
266	        LoadGmToUb(resInLocal_, resGM_[static_cast<uint64_t>(rowBase) * N], static_cast<uint32_t>(count));
267	        resInQueue_.EnQue(resInLocal_);
268	    }
269	
270	    __aicore__ inline void CopyOutY(int32_t rowBase, int32_t count)
271	    {
272	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
273	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowBase) * N], yOutLocal_, static_cast<uint32_t>(count));
274	        yOutQueue_.FreeTensor(yOutLocal_);
275	    }
276	
277	    __aicore__ inline void ComputeSingleRow()
278	    {
279	        const uint32_t reduceShape[2] = {1U, static_cast<uint32_t>(N)};
280	        const uint32_t scaleSrcShape[2] = {1U, 1U};
281	        const uint32_t scaleDstShape[2] = {1U, static_cast<uint32_t>(N)};
282	
283	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
284	        scaleLocal_ = scaleBuf_.Get<float>();
285	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
286	        sumLocal_ = sumBuf_.Get<float>();
287	        PrepareInvRmsTensor(invRmsLocal_, invRmsBuf_);
288	        scaleBroadcastTmpLocal_ = scaleBroadcastTmpBuf_.Get<uint8_t>();
289	
290	        hsInLocal_ = hsInQueue_.DeQue<dataType>();
291	        resInLocal_ = resInQueue_.DeQue<dataType>();
292	        PrepareInputTensorHelper<dataType>(hsLocal_, hsInLocal_, hsCastBuf_, N);
293	        PrepareInputTensorHelper<dataType>(resLocal_, resInLocal_, resCastBuf_, N);
294	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
295	
296	        // x = hidden_states + residual
297	        AscendC::Add(yLocal_, hsLocal_, resLocal_, N);
298	        // x_sq = x * x
299	        AscendC::Mul(yLocal_, yLocal_, yLocal_, N);
300	        // sum_sq = reduce_sum(x_sq)
301	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
302	            sumLocal_, yLocal_, reduceTmpLocal_, reduceShape, true);
303	        // rms_val = sum_sq * invN + eps
304	        AscendC::Muls(sumLocal_, sumLocal_, invN, 1);
305	        AscendC::Adds(sumLocal_, sumLocal_, eps, 1);
306	        // inv_rms = rsqrt(rms_val)
307	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
308	        AscendC::PipeBarrier<PIPE_V>();
309	
310	        // broadcast inv_rms to full row width
311	        AscendC::Broadcast<float, 2, 1>(
312	            scaleLocal_, invRmsLocal_, scaleDstShape, scaleSrcShape, scaleBroadcastTmpLocal_);
313	
314	        // Reload x (hs+res) for the output computation
315	        AscendC::Add(yLocal_, hsLocal_, resLocal_, N);
316	        // y = x * inv_rms * weight
317	        AscendC::Mul(yLocal_, yLocal_, scaleLocal_, N);
318	        AscendC::Mul(yLocal_, yLocal_, weightLocal_, N);
319	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, N);
320	
321	        hsInQueue_.FreeTensor(hsInLocal_);
322	        resInQueue_.FreeTensor(resInLocal_);
323	        yOutQueue_.EnQue(yOutLocal_);
324	    }
325	
326	    __aicore__ inline void ComputeRows(int32_t tileSize)
327	    {
328	        const uint32_t reduceShape[2] = {
329	            static_cast<uint32_t>(kMergeRowFactor),
330	            static_cast<uint32_t>(N),
331	        };
332	        const uint32_t scaleSrcShape[2] = {
333	            static_cast<uint32_t>(kMergeRowFactor),
334	            1U,
335	        };
336	        const uint32_t scaleDstShape[2] = {
337	            static_cast<uint32_t>(kMergeRowFactor),
338	            static_cast<uint32_t>(N),
339	        };
340	
341	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
342	        scaleLocal_ = scaleBuf_.Get<float>();
343	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
344	        sumLocal_ = sumBuf_.Get<float>();
345	        PrepareInvRmsTensor(invRmsLocal_, invRmsBuf_);
346	        scaleBroadcastTmpLocal_ = scaleBroadcastTmpBuf_.Get<uint8_t>();
347	
348	        hsInLocal_ = hsInQueue_.DeQue<dataType>();
349	        resInLocal_ = resInQueue_.DeQue<dataType>();
350	        PrepareInputTensorHelper<dataType>(hsLocal_, hsInLocal_, hsCastBuf_, tileSize);
351	        PrepareInputTensorHelper<dataType>(resLocal_, resInLocal_, resCastBuf_, tileSize);
352	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
353	
354	        // x = hidden_states + residual
355	        AscendC::Add(yLocal_, hsLocal_, resLocal_, tileSize);
356	        // x_sq = x * x
357	        AscendC::Mul(yLocal_, yLocal_, yLocal_, tileSize);
358	        // sum_sq = reduce_sum(x_sq)
359	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
360	            sumLocal_, yLocal_, reduceTmpLocal_, reduceShape, true);
361	        // rms_val = sum_sq * invN + eps
362	        AscendC::Muls(sumLocal_, sumLocal_, invN, kMergeRowFactor);
363	        AscendC::Adds(sumLocal_, sumLocal_, eps, kMergeRowFactor);
364	        // inv_rms = rsqrt(rms_val)
365	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, kMergeRowFactor);
366	        AscendC::PipeBarrier<PIPE_V>();
367	
368	        // broadcast inv_rms to full width
369	        AscendC::Broadcast<float, 2, 1>(
370	            scaleLocal_, invRmsLocal_, scaleDstShape, scaleSrcShape, scaleBroadcastTmpLocal_);
371	
372	        // Reload x
373	        AscendC::Add(yLocal_, hsLocal_, resLocal_, tileSize);
374	        // y = x * inv_rms * weight
375	        AscendC::Mul(yLocal_, yLocal_, scaleLocal_, tileSize);
376	        AscendC::Mul(yLocal_, yLocal_, weightTileLocal_, tileSize);
377	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, tileSize);
378	
379	        hsInQueue_.FreeTensor(hsInLocal_);
380	        resInQueue_.FreeTensor(resInLocal_);
381	        yOutQueue_.EnQue(yOutLocal_);
382	    }
383	
384	    __aicore__ inline void ProcessSingleRow(int rowIdx)
385	    {
386	        CopyInHs(rowIdx, N);
387	        CopyInRes(rowIdx, N);
388	        ComputeSingleRow();
389	        CopyOutY(rowIdx, N);
390	    }
391	
392	    __aicore__ inline void ProcessRows(int rowBase, int validRows)
393	    {
394	        if (validRows < kMergeRowFactor) {
395	            for (int r = 0; r < validRows; ++r) {
396	                ProcessSingleRow(rowBase + r);
397	            }
398	            return;
399	        }
400	
401	        const int tileSize = kMergeRowFactor * N;
402	        CopyInHs(rowBase, tileSize);
403	        CopyInRes(rowBase, tileSize);
404	        ComputeRows(tileSize);
405	        CopyOutY(rowBase, tileSize);
406	    }
407	
408	private:
409	    int32_t M = 0;
410	    int32_t N = 0;
411	    int32_t blockM = 0;
412	    int32_t usedCoreNum = 0;
413	    int32_t tasksPerCore = 0;
414	    int32_t rowFactor = 0;
415	    float eps = 0.0f;
416	    float invN = 0.0f;
417	    int subBlockRows_ = 0;
418	    int rowLoops_ = 0;
419	
420	    AscendC::TPipe pipe;
421	    AscendC::GlobalTensor<dataType> hsGM_;
422	    AscendC::GlobalTensor<dataType> resGM_;
423	    AscendC::GlobalTensor<dataType> weightGM_;
424	    AscendC::GlobalTensor<dataType> yGM_;
425	
426	    AscendC::TBuf<AscendC::TPosition::VECCALC> weightBuf_;
427	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> hsInQueue_;
428	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> resInQueue_;
429	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
430	    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBuf_;
431	    AscendC::TBuf<AscendC::TPosition::VECCALC> weightTileBuf_;
432	    AscendC::TBuf<AscendC::TPosition::VECCALC> weightBroadcastTmpBuf_;
433	    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBroadcastTmpBuf_;
434	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
435	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
436	    AscendC::TBuf<AscendC::TPosition::VECCALC> invRmsBuf_;
437	    AscendC::TBuf<AscendC::TPosition::VECCALC> hsCastBuf_;
438	    AscendC::TBuf<AscendC::TPosition::VECCALC> resCastBuf_;
439	    AscendC::TBuf<AscendC::TPosition::VECCALC> weightCastBuf_;
440	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
441	
442	    AscendC::LocalTensor<dataType> weightInLocal_;
443	    AscendC::LocalTensor<dataType> hsInLocal_;
444	    AscendC::LocalTensor<dataType> resInLocal_;
445	    AscendC::LocalTensor<dataType> yOutLocal_;
446	    AscendC::LocalTensor<float> weightLocal_;
447	    AscendC::LocalTensor<float> hsLocal_;
448	    AscendC::LocalTensor<float> resLocal_;
449	    AscendC::LocalTensor<float> yLocal_;
450	    AscendC::LocalTensor<float> scaleLocal_;
451	    AscendC::LocalTensor<float> weightTileLocal_;
452	    AscendC::LocalTensor<float> invRmsLocal_;
453	    AscendC::LocalTensor<uint8_t> weightBroadcastTmpLocal_;
454	    AscendC::LocalTensor<uint8_t> scaleBroadcastTmpLocal_;
455	    AscendC::LocalTensor<uint8_t> reduceTmpLocal_;
456	    AscendC::LocalTensor<float> sumLocal_;
457	
458	    // Non-template version of PrepareInputTensorHelper for member access to weightLocal_
459	    template <typename T1>
460	    __aicore__ inline void PrepareInputTensor(
461	        AscendC::LocalTensor<float> &dst,
462	        AscendC::LocalTensor<T1> &src,
463	        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
464	        int32_t count)
465	    {
466	        if constexpr (std::is_same_v<T1, float>) {
467	            dst = src.template ReinterpretCast<float>();
468	        } else {
469	            dst = castBuf.Get<float>();
470	            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
471	            AscendC::PipeBarrier<PIPE_V>();
472	        }
473	    }
474	
475	    __aicore__ inline void PrepareInvRmsTensor(
476	        AscendC::LocalTensor<float> &dst,
477	        AscendC::TBuf<AscendC::TPosition::VECCALC> &buf)
478	    {
479	        dst = buf.Get<float>();
480	    }
