483	// =========================================================================
484	// Strategy 2: single_row — preferred when 1024 < N <= 8192
485	// =========================================================================
486	
487	template <typename dataType>
488	class FusedAddRmsnormSingleRowKernel : public FusedAddRmsnormKernelBase<dataType> {
489	public:
490	    __aicore__ inline void Init(
491	        GM_ADDR hiddenStates, GM_ADDR residual, GM_ADDR weight, GM_ADDR y,
492	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
493	        int32_t tasksPerCore, float eps, float invN)
494	    {
495	        this->InitBase(hiddenStates, residual, weight, y, M, N, blockM, usedCoreNum, tasksPerCore, eps, invN);
496	
497	        if ASCEND_IS_AIV {
498	            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
499	            pipe.InitBuffer(weightBuf_, N * sizeof(dataType));
500	            pipe.InitBuffer(hsInQueue_, BUFFER_NUM, N * sizeof(dataType));
501	            pipe.InitBuffer(resInQueue_, BUFFER_NUM, N * sizeof(dataType));
502	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, N * sizeof(dataType));
503	            pipe.InitBuffer(reduceBuf_, N * sizeof(float));
504	            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
505	            pipe.InitBuffer(invRmsBuf_, sizeof(float));
506	            if constexpr (!std::is_same_v<dataType, float>) {
507	                pipe.InitBuffer(hsCastBuf_, N * sizeof(float));
508	                pipe.InitBuffer(resCastBuf_, N * sizeof(float));
509	                pipe.InitBuffer(weightCastBuf_, N * sizeof(float));
510	                pipe.InitBuffer(yCastBuf_, N * sizeof(float));
511	            }
512	
513	            weightInLocal_ = weightBuf_.Get<dataType>();
514	            LoadGmToUb(weightInLocal_, weightGM_, static_cast<uint32_t>(N));
515	            AscendC::PipeBarrier<PIPE_MTE2>();
516	            AscendC::PipeBarrier<PIPE_ALL>();
517	            PrepareInputTensorHelper<dataType>(weightLocal_, weightInLocal_, weightCastBuf_, N);
518	        }
519	    }
520	
521	    __aicore__ inline void Process()
522	    {
523	        if ASCEND_IS_AIV {
524	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
525	            const int subBlockIdx = AscendC::GetSubBlockIdx();
526	
527	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
528	                const int bx = coreIdx * tasksPerCore + localIdx;
529	                if (bx >= BlockCountHelper(M, blockM)) {
530	                    continue;
531	                }
532	
533	                for (int row = 0; row < subBlockRows_; ++row) {
534	                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
535	                    if (rowIdx < M) {
536	                        ProcessRow(rowIdx);
537	                    }
538	                }
539	            }
540	        }
541	    }
542	
543	private:
544	    __aicore__ inline void CopyInHs(int32_t rowIdx)
545	    {
546	        hsInLocal_ = hsInQueue_.AllocTensor<dataType>();
547	        LoadGmToUb(hsInLocal_, hsGM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
548	        hsInQueue_.EnQue(hsInLocal_);
549	    }
550	
551	    __aicore__ inline void CopyInRes(int32_t rowIdx)
552	    {
553	        resInLocal_ = resInQueue_.AllocTensor<dataType>();
554	        LoadGmToUb(resInLocal_, resGM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
555	        resInQueue_.EnQue(resInLocal_);
556	    }
557	
558	    __aicore__ inline void CopyOutY(int32_t rowIdx)
559	    {
560	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
561	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N], yOutLocal_, static_cast<uint32_t>(N));
562	        yOutQueue_.FreeTensor(yOutLocal_);
563	    }
564	
565	    __aicore__ inline void ComputeRow()
566	    {
567	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
568	        invRmsLocal_ = invRmsBuf_.Get<float>();
569	        reduceLocal_ = reduceBuf_.Get<float>();
570	        sumLocal_ = sumBuf_.Get<float>();
571	
572	        hsInLocal_ = hsInQueue_.DeQue<dataType>();
573	        resInLocal_ = resInQueue_.DeQue<dataType>();
574	        PrepareInputTensorHelper<dataType>(hsLocal_, hsInLocal_, hsCastBuf_, N);
575	        PrepareInputTensorHelper<dataType>(resLocal_, resInLocal_, resCastBuf_, N);
576	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
577	
578	        // x = hidden_states + residual
579	        AscendC::Add(yLocal_, hsLocal_, resLocal_, N);
580	        // x_sq = x * x
581	        AscendC::Mul(yLocal_, yLocal_, yLocal_, N);
582	        // sum_sq = reduce_sum(x_sq)
583	        AscendC::ReduceSum<float>(sumLocal_, yLocal_, reduceLocal_, N);
584	
585	        float meanSq = sumLocal_.GetValue(0) * invN + eps;
586	        AscendC::Duplicate(sumLocal_, meanSq, 1);
587	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
588	        AscendC::PipeBarrier<PIPE_ALL>();
589	        float invRms = invRmsLocal_.GetValue(0);
590	        AscendC::PipeBarrier<PIPE_ALL>();
591	
592	        // Reload x = hidden_states + residual
593	        AscendC::Add(yLocal_, hsLocal_, resLocal_, N);
594	        // y = x * inv_rms * weight
595	        AscendC::Muls(yLocal_, yLocal_, invRms, N);
596	        AscendC::Mul(yLocal_, yLocal_, weightLocal_, N);
597	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, N);
598	
599	        hsInQueue_.FreeTensor(hsInLocal_);
600	        resInQueue_.FreeTensor(resInLocal_);
601	        yOutQueue_.EnQue(yOutLocal_);
602	    }
603	
604	    __aicore__ inline void ProcessRow(int rowIdx)
605	    {
606	        CopyInHs(rowIdx);
607	        CopyInRes(rowIdx);
608	        ComputeRow();
609	        CopyOutY(rowIdx);
610	    }
611	
612	private:
613	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> hsInQueue_;
614	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> resInQueue_;
615	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
616	    AscendC::TBuf<AscendC::TPosition::VECCALC> weightBuf_;
617	    AscendC::TBuf<AscendC::TPosition::VECCALC> hsCastBuf_;
618	    AscendC::TBuf<AscendC::TPosition::VECCALC> resCastBuf_;
619	    AscendC::TBuf<AscendC::TPosition::VECCALC> weightCastBuf_;
620	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
621	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
622	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
623	    AscendC::TBuf<AscendC::TPosition::VECCALC> invRmsBuf_;
624	
625	    AscendC::LocalTensor<dataType> hsInLocal_;
626	    AscendC::LocalTensor<dataType> resInLocal_;
627	    AscendC::LocalTensor<dataType> yOutLocal_;
628	    AscendC::LocalTensor<dataType> weightInLocal_;
629	    AscendC::LocalTensor<float> hsLocal_;
630	    AscendC::LocalTensor<float> resLocal_;
631	    AscendC::LocalTensor<float> yLocal_;
632	    AscendC::LocalTensor<float> weightLocal_;
633	    AscendC::LocalTensor<float> invRmsLocal_;
634	    AscendC::LocalTensor<float> reduceLocal_;
635	    AscendC::LocalTensor<float> sumLocal_;
636	
637	    using FusedAddRmsnormKernelBase<dataType>::M;
638	    using FusedAddRmsnormKernelBase<dataType>::N;
639	    using FusedAddRmsnormKernelBase<dataType>::blockM;
640	    using FusedAddRmsnormKernelBase<dataType>::usedCoreNum;
641	    using FusedAddRmsnormKernelBase<dataType>::tasksPerCore;
642	    using FusedAddRmsnormKernelBase<dataType>::eps;
643	    using FusedAddRmsnormKernelBase<dataType>::invN;
644	    using FusedAddRmsnormKernelBase<dataType>::subBlockRows_;
645	    using FusedAddRmsnormKernelBase<dataType>::pipe;
646	    using FusedAddRmsnormKernelBase<dataType>::hsGM_;
647	    using FusedAddRmsnormKernelBase<dataType>::resGM_;
648	    using FusedAddRmsnormKernelBase<dataType>::weightGM_;
649	    using FusedAddRmsnormKernelBase<dataType>::yGM_;
650	};
