652	// =========================================================================
653	// Strategy 3: splitd — preferred when N > 8192
654	// =========================================================================
655	
656	template <typename dataType>
657	class FusedAddRmsnormSplitDKernel : public FusedAddRmsnormKernelBase<dataType> {
658	public:
659	    __aicore__ inline void Init(
660	        GM_ADDR hiddenStates, GM_ADDR residual, GM_ADDR weight, GM_ADDR y,
661	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
662	        int32_t tasksPerCore, float eps, float invN)
663	    {
664	        this->InitBase(hiddenStates, residual, weight, y, M, N, blockM, usedCoreNum, tasksPerCore, eps, invN);
665	
666	        if ASCEND_IS_AIV {
667	            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
668	            pipe.InitBuffer(hsInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
669	            pipe.InitBuffer(resInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
670	            pipe.InitBuffer(weightInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
671	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
672	            pipe.InitBuffer(reduceBuf_, kBlockN * sizeof(float));
673	            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
674	            pipe.InitBuffer(tempBuf_, kTileFloatBytes);
675	            pipe.InitBuffer(invRmsBuf_, sizeof(float));
676	            if constexpr (!std::is_same_v<dataType, float>) {
677	                pipe.InitBuffer(hsCastBuf_, kTileFloatBytes);
678	                pipe.InitBuffer(resCastBuf_, kTileFloatBytes);
679	                pipe.InitBuffer(weightCastBuf_, kTileFloatBytes);
680	                pipe.InitBuffer(yCastBuf_, kTileFloatBytes);
681	            }
682	        }
683	    }
684	
685	    __aicore__ inline void Process()
686	    {
687	        if ASCEND_IS_AIV {
688	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
689	            const int subBlockIdx = AscendC::GetSubBlockIdx();
690	
691	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
692	                const int bx = coreIdx * tasksPerCore + localIdx;
693	                if (bx >= BlockCountHelper(M, blockM)) {
694	                    continue;
695	                }
696	
697	                for (int row = 0; row < subBlockRows_; ++row) {
698	                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
699	                    if (rowIdx < M) {
700	                        ProcessRow(rowIdx);
701	                    }
702	                }
703	            }
704	        }
705	    }
706	
707	private:
708	    static constexpr int kBlockN = 1024;
709	    static constexpr uint32_t kTileFloatBytes = kBlockN * sizeof(float);
710	
711	    __aicore__ inline int32_t NumTiles() const
712	    {
713	        return (N + kBlockN - 1) / kBlockN;
714	    }
715	
716	    __aicore__ inline int32_t GetValidN(int32_t colBase) const
717	    {
718	        return (colBase + kBlockN <= N) ? kBlockN : (N - colBase);
719	    }
720	
721	    __aicore__ inline void CopyInHs(int32_t rowIdx, int32_t colBase, int32_t validN)
722	    {
723	        hsInLocal_ = hsInQueue_.AllocTensor<dataType>();
724	        LoadGmToUb(hsInLocal_, hsGM_[static_cast<uint64_t>(rowIdx) * N + colBase], static_cast<uint32_t>(validN));
725	        hsInQueue_.EnQue(hsInLocal_);
726	    }
727	
728	    __aicore__ inline void CopyInRes(int32_t rowIdx, int32_t colBase, int32_t validN)
729	    {
730	        resInLocal_ = resInQueue_.AllocTensor<dataType>();
731	        LoadGmToUb(resInLocal_, resGM_[static_cast<uint64_t>(rowIdx) * N + colBase], static_cast<uint32_t>(validN));
732	        resInQueue_.EnQue(resInLocal_);
733	    }
734	
735	    __aicore__ inline void CopyInWeight(int32_t colBase, int32_t validN)
736	    {
737	        weightInLocal_ = weightInQueue_.AllocTensor<dataType>();
738	        LoadGmToUb(weightInLocal_, weightGM_[colBase], static_cast<uint32_t>(validN));
739	        weightInQueue_.EnQue(weightInLocal_);
740	    }
741	
742	    __aicore__ inline void CopyOutY(int32_t rowIdx, int32_t colBase, int32_t validN)
743	    {
744	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
745	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N + colBase], yOutLocal_, static_cast<uint32_t>(validN));
746	        yOutQueue_.FreeTensor(yOutLocal_);
747	    }
748	
749	    __aicore__ inline float ComputeInvRms(int32_t rowIdx)
750	    {
751	        reduceLocal_ = reduceBuf_.Get<float>();
752	        sumLocal_ = sumBuf_.Get<float>();
753	        tempLocal_ = tempBuf_.Get<float>();
754	        invRmsLocal_ = invRmsBuf_.Get<float>();
755	        float sumSq = 0.0f;
756	
757	        for (int by = 0; by < NumTiles(); ++by) {
758	            const int colBase = by * kBlockN;
759	            const int validN = GetValidN(colBase);
760	
761	            CopyInHs(rowIdx, colBase, validN);
762	            CopyInRes(rowIdx, colBase, validN);
763	
764	            hsInLocal_ = hsInQueue_.DeQue<dataType>();
765	            resInLocal_ = resInQueue_.DeQue<dataType>();
766	            PrepareInputTensorHelper<dataType>(hsLocal_, hsInLocal_, hsCastBuf_, validN);
767	            PrepareInputTensorHelper<dataType>(resLocal_, resInLocal_, resCastBuf_, validN);
768	            // x = hidden_states + residual
769	            AscendC::Add(tempLocal_, hsLocal_, resLocal_, validN);
770	            AscendC::Mul(tempLocal_, tempLocal_, tempLocal_, validN);
771	            AscendC::ReduceSum<float>(sumLocal_, tempLocal_, reduceLocal_, validN);
772	            sumSq += sumLocal_.GetValue(0);
773	            hsInQueue_.FreeTensor(hsInLocal_);
774	            resInQueue_.FreeTensor(resInLocal_);
775	        }
776	
777	        AscendC::Duplicate(sumLocal_, sumSq * invN + eps, 1);
778	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
779	        AscendC::PipeBarrier<PIPE_ALL>();
780	        float invRms = invRmsLocal_.GetValue(0);
781	        AscendC::PipeBarrier<PIPE_ALL>();
782	        return invRms;
783	    }
784	
785	    __aicore__ inline void ComputeTile(float invRms, int32_t validN)
786	    {
787	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
788	        hsInLocal_ = hsInQueue_.DeQue<dataType>();
789	        resInLocal_ = resInQueue_.DeQue<dataType>();
790	        weightInLocal_ = weightInQueue_.DeQue<dataType>();
791	        PrepareInputTensorHelper<dataType>(hsLocal_, hsInLocal_, hsCastBuf_, validN);
792	        PrepareInputTensorHelper<dataType>(resLocal_, resInLocal_, resCastBuf_, validN);
793	        PrepareInputTensorHelper<dataType>(weightLocal_, weightInLocal_, weightCastBuf_, validN);
794	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
795	        // x = hidden_states + residual
796	        AscendC::Add(yLocal_, hsLocal_, resLocal_, validN);
797	        // y = x * inv_rms * weight
798	        AscendC::Muls(yLocal_, yLocal_, invRms, validN);
799	        AscendC::Mul(yLocal_, yLocal_, weightLocal_, validN);
800	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, validN);
801	        hsInQueue_.FreeTensor(hsInLocal_);
802	        resInQueue_.FreeTensor(resInLocal_);
803	        weightInQueue_.FreeTensor(weightInLocal_);
804	        yOutQueue_.EnQue(yOutLocal_);
805	    }
806	
807	    __aicore__ inline void ProcessRow(int rowIdx)
808	    {
809	        float invRms = ComputeInvRms(rowIdx);
810	
811	        for (int by = 0; by < NumTiles(); ++by) {
812	            const int colBase = by * kBlockN;
813	            const int validN = GetValidN(colBase);
814	            CopyInHs(rowIdx, colBase, validN);
815	            CopyInRes(rowIdx, colBase, validN);
816	            CopyInWeight(colBase, validN);
817	            ComputeTile(invRms, validN);
818	            CopyOutY(rowIdx, colBase, validN);
819	        }
820	    }
821	
822	private:
823	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> hsInQueue_;
824	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> resInQueue_;
825	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> weightInQueue_;
826	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
827	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
828	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
829	    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuf_;
830	    AscendC::TBuf<AscendC::TPosition::VECCALC> invRmsBuf_;
831	    AscendC::TBuf<AscendC::TPosition::VECCALC> hsCastBuf_;
832	    AscendC::TBuf<AscendC::TPosition::VECCALC> resCastBuf_;
833	    AscendC::TBuf<AscendC::TPosition::VECCALC> weightCastBuf_;
834	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
835	
836	    AscendC::LocalTensor<dataType> hsInLocal_;
837	    AscendC::LocalTensor<dataType> resInLocal_;
838	    AscendC::LocalTensor<dataType> weightInLocal_;
839	    AscendC::LocalTensor<dataType> yOutLocal_;
840	    AscendC::LocalTensor<float> invRmsLocal_;
841	    AscendC::LocalTensor<float> hsLocal_;
842	    AscendC::LocalTensor<float> resLocal_;
843	    AscendC::LocalTensor<float> weightLocal_;
844	    AscendC::LocalTensor<float> yLocal_;
845	    AscendC::LocalTensor<float> reduceLocal_;
846	    AscendC::LocalTensor<float> sumLocal_;
847	    AscendC::LocalTensor<float> tempLocal_;
848	
849	    using FusedAddRmsnormKernelBase<dataType>::M;
850	    using FusedAddRmsnormKernelBase<dataType>::N;
851	    using FusedAddRmsnormKernelBase<dataType>::blockM;
852	    using FusedAddRmsnormKernelBase<dataType>::usedCoreNum;
853	    using FusedAddRmsnormKernelBase<dataType>::tasksPerCore;
854	    using FusedAddRmsnormKernelBase<dataType>::eps;
855	    using FusedAddRmsnormKernelBase<dataType>::invN;
856	    using FusedAddRmsnormKernelBase<dataType>::subBlockRows_;
857	    using FusedAddRmsnormKernelBase<dataType>::pipe;
858	    using FusedAddRmsnormKernelBase<dataType>::hsGM_;
859	    using FusedAddRmsnormKernelBase<dataType>::resGM_;
860	    using FusedAddRmsnormKernelBase<dataType>::weightGM_;
861	    using FusedAddRmsnormKernelBase<dataType>::yGM_;
862	};
863	
864	// =========================================================================
865	// Shared dtype-dispatch helper
866	// =========================================================================
867	
868	template <template <typename> class Kernel, typename... ExtraArgs>
869	__aicore__ inline void DispatchFusedAddRmsnorm(
870	    GM_ADDR hiddenStates, GM_ADDR residual, GM_ADDR weight, GM_ADDR y,
871	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
872	    int32_t tasksPerCore, float eps, float invN,
873	    int64_t dtypeFlag, ExtraArgs... extraArgs)
874	{
