// FusedResidualRmsNormBackward op_host — tiling + EXEC_KERNEL_CMD launch
//
// The kernel computes per-core local_grad_weight and writes it to workspace.
// The host then uses at::sum to reduce workspace across cores into grad_weight.

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>
#include <ATen/ATen.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_fused_residual_rms_norm_backward.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_TILE_H = 256;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

std::tuple<at::Tensor, at::Tensor, at::Tensor> fused_residual_rms_norm_backward(
    const at::Tensor& grad_output,
    const at::Tensor& x,
    const at::Tensor& normalized,
    const at::Tensor& rstd,
    const at::Tensor& weight)
{
    // Input validation
    TORCH_CHECK(grad_output.dim() == 3, "grad_output must be [B, S, H]");
    TORCH_CHECK(grad_output.scalar_type() == at::kBFloat16 || grad_output.scalar_type() == at::kHalf,
                "grad_output must be bfloat16 or float16");
    TORCH_CHECK(grad_output.is_contiguous(), "grad_output must be contiguous");

    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(normalized.scalar_type() == at::kFloat, "normalized must be float32");
    TORCH_CHECK(rstd.scalar_type() == at::kFloat, "rstd must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");

    int32_t B = static_cast<int32_t>(grad_output.sizes()[0]);
    int32_t S = static_cast<int32_t>(grad_output.sizes()[1]);
    int32_t H = static_cast<int32_t>(grad_output.sizes()[2]);

    TORCH_CHECK(static_cast<int32_t>(x.sizes()[0]) == B && static_cast<int32_t>(x.sizes()[1]) == S &&
                    static_cast<int32_t>(x.sizes()[2]) == H,
                "x shape mismatch");
    TORCH_CHECK(static_cast<int32_t>(normalized.sizes()[2]) == H, "normalized shape mismatch");
    TORCH_CHECK(static_cast<int32_t>(rstd.sizes()[2]) == 1, "rstd last dim must be 1");
    TORCH_CHECK(static_cast<int32_t>(weight.sizes()[0]) == H, "weight shape mismatch");

    // Platform query
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    int32_t numCores = static_cast<int32_t>(std::min<int64_t>(DEFAULT_NUM_PHYSICAL_CORES,
                                                               std::max<int64_t>(1, coreNum)));

    // Tiling
    int32_t totalRows = B * S;
    int32_t rowsPerCore = (totalRows + numCores - 1) / numCores;
    int32_t tileH = DEFAULT_TILE_H;
    int32_t numHTiles = (H + tileH - 1) / tileH;

    // dtype flag: 1=fp16, 2=bf16
    int64_t dtypeFlag = (grad_output.scalar_type() == at::kHalf) ? 1 : 2;

    // Allocate outputs
    auto grad_hs = at::empty({B, S, H}, grad_output.options().dtype(grad_output.scalar_type()));
    auto grad_res = at::empty({B, S, H}, grad_output.options().dtype(grad_output.scalar_type()));
    // Workspace for per-core partial grad_weight sums
    auto workspace = at::empty({numCores, H}, at::TensorOptions().dtype(at::kFloat).device(grad_output.device()));

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    uint32_t blockDim = static_cast<uint32_t>(numCores);

    EXEC_KERNEL_CMD(fused_residual_rms_norm_backward, blockDim,
                    grad_output, x, normalized, rstd, weight,
                    grad_hs, grad_res, workspace,
                    B, S, H, totalRows, rowsPerCore, tileH, numHTiles, numCores,
                    dtypeFlag);

    // Reduce workspace across cores → grad_weight (device-side sum)
    auto grad_w = at::sum(workspace, 0).to(at::kFloat);

    return std::make_tuple(grad_hs, grad_res, grad_w);
}

}  // namespace ascend_kernel
