// AscendC kernel: FusedResidualRmsNormBackward
// Computes gradients for fused residual addition + RMSNorm backward pass.
//
// Inputs (GM):
//   grad_output  [B,S,H] bf16/fp16 — gradient from next layer
//   x            [B,S,H] f32       — saved hidden_states + residual
//   normalized   [B,S,H] f32       — saved normalized values from forward
//   rstd         [B,S,1] f32       — reciprocal std dev from forward
//   weight       [H]    f32        — RMSNorm scale parameter
//
// Outputs (GM):
//   grad_hidden_states  [B,S,H] bf16/fp16
//   grad_residual       [B,S,H] bf16/fp16
//   workspace           [numCores, H] f32 — per-core partial grad_weight sums
//                                            (host reduces via at::sum)

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T>& dst,
    const AscendC::GlobalTensor<T>& src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T>& dst,
    const AscendC::LocalTensor<T>& src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// Kernel class
// Template T: half or bfloat16_t for grad_output / output tensors
// All internal computation uses float32.
// =========================================================================

template <typename T>
class KernelFusedResidualRmsNormBackward {
public:
    __aicore__ inline void Init(
        GM_ADDR grad_output, GM_ADDR x, GM_ADDR normalized,
        GM_ADDR rstd, GM_ADDR weight,
        GM_ADDR grad_hidden_states, GM_ADDR grad_residual,
        GM_ADDR workspace,
        int32_t B, int32_t S, int32_t H,
        int32_t totalRows, int32_t rowsPerCore,
        int32_t tileH, int32_t numHTiles,
        int32_t numCores)
    {
        B_ = B; S_ = S; H_ = H;
        totalRows_ = totalRows; rowsPerCore_ = rowsPerCore;
        tileH_ = tileH; numHTiles_ = numHTiles;
        numCores_ = numCores;

        uint64_t bsLen = static_cast<uint64_t>(B) * S * H;
        uint64_t bsLenF = static_cast<uint64_t>(B) * S;

        goGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(grad_output), bsLen);
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(x), bsLen);
        normGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(normalized), bsLen);
        rstdGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(rstd), bsLenF);
        weightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(weight), H_);
        ghsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(grad_hidden_states), bsLen);
        gresGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(grad_residual), bsLen);
        wsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(workspace),
                              static_cast<uint64_t>(numCores_) * H_);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        // TQue (double-buffered for GM↔UB DMA)
        pipe.InitBuffer(inQGo_, BUFFER_NUM, tileH_ * sizeof(T));
        pipe.InitBuffer(inQNorm_, BUFFER_NUM, tileH_ * sizeof(float));
        pipe.InitBuffer(inQW_, BUFFER_NUM, tileH_ * sizeof(float));
        pipe.InitBuffer(outQ_, BUFFER_NUM, tileH_ * sizeof(T));

        // TBuf (computation buffers)
        if constexpr (!std::is_same_v<T, float>) {
            pipe.InitBuffer(goCastBuf_, tileH_ * sizeof(float));
        }
        pipe.InitBuffer(gnBuf_, tileH_ * sizeof(float));
        pipe.InitBuffer(prodBuf_, tileH_ * sizeof(float));
        pipe.InitBuffer(gxF32Buf_, tileH_ * sizeof(float));
        pipe.InitBuffer(meanBcastBuf_, tileH_ * sizeof(float));
        pipe.InitBuffer(rstdBcastBuf_, tileH_ * sizeof(float));
        pipe.InitBuffer(reduceTmpBuf_, 2 * tileH_ * sizeof(uint8_t));
        pipe.InitBuffer(lwTileBuf_, tileH_ * sizeof(float));
        pipe.InitBuffer(lwAddBuf_, tileH_ * sizeof(float));

        // Persistent local_grad_weight (H floats, lives across all rows)
        pipe.InitBuffer(localGWBuf_, H_ * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            // Use AscendC::GetBlockIdx() for core index
            int32_t coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            int32_t rowStart = coreIdx * rowsPerCore_;
            int32_t rowEnd = rowStart + rowsPerCore_;
            if (rowEnd > totalRows_) { rowEnd = totalRows_; }
            int32_t numLocalRows = rowEnd - rowStart;

            // Zero-initialize local_grad_weight
            {
                AscendC::LocalTensor<float> lwAll = localGWBuf_.Get<float>();
                AscendC::Duplicate(lwAll, 0.0f, H_);
                AscendC::PipeBarrier<PIPE_V>();
            }

            // --- Per-row two-pass processing ---
            for (int32_t lr = 0; lr < numLocalRows; ++lr) {
                int32_t rowIdx = rowStart + lr;
                int32_t b = static_cast<int32_t>(static_cast<uint64_t>(rowIdx) / static_cast<uint64_t>(S_));
                int32_t s = rowIdx - b * S_;

                // Pass 1: accumulate row_sum (for mean) and local_grad_weight
                float rowSum = 0.0f;
                for (int32_t ht = 0; ht < numHTiles_; ++ht) {
                    int32_t hStart = ht * tileH_;
                    int32_t curH = (hStart + tileH_ <= H_) ? tileH_ : (H_ - hStart);
                    CopyIn(b, s, hStart, curH);
                    ComputePass1(curH, hStart, rowSum);
                }

                // row_mean = row_sum / H
                float rowMean = rowSum * (1.0f / static_cast<float>(H_));

                // Load rstd[b,s] scalar
                float rstdVal = LoadRstd(b, s);

                // Pass 2: compute grad_x and write outputs
                for (int32_t ht = 0; ht < numHTiles_; ++ht) {
                    int32_t hStart = ht * tileH_;
                    int32_t curH = (hStart + tileH_ <= H_) ? tileH_ : (H_ - hStart);
                    CopyIn(b, s, hStart, curH);
                    ComputePass2(curH, rowMean, rstdVal);
                    CopyOut(b, s, hStart, curH);
                }
            }

            // --- Write local_grad_weight to workspace[coreIdx, :] ---
            WriteLocalGWToWorkspace(coreIdx);
        }
    }

private:
    // -----------------------------------------------------------------------
    // CopyIn: Load one tile of grad_output, normalized, weight
    // -----------------------------------------------------------------------
    __aicore__ inline void CopyIn(int32_t b, int32_t s, int32_t hStart, int32_t curH)
    {
        uint64_t rowOff = static_cast<uint64_t>(b) * S_ * H_ + static_cast<uint64_t>(s) * H_;

        // grad_output tile
        goInLocal_ = inQGo_.AllocTensor<T>();
        LoadGmToUb(goInLocal_, goGM_[rowOff + hStart], static_cast<uint32_t>(curH));
        inQGo_.EnQue(goInLocal_);

        // normalized tile
        normInLocal_ = inQNorm_.AllocTensor<float>();
        LoadGmToUb(normInLocal_, normGM_[rowOff + hStart], static_cast<uint32_t>(curH));
        inQNorm_.EnQue(normInLocal_);

        // weight tile
        wInLocal_ = inQW_.AllocTensor<float>();
        LoadGmToUb(wInLocal_, weightGM_[hStart], static_cast<uint32_t>(curH));
        inQW_.EnQue(wInLocal_);
    }

    // -----------------------------------------------------------------------
    // ComputePass1: Accumulate row_sum (for mean) + local_grad_weight
    // -----------------------------------------------------------------------
    __aicore__ inline void ComputePass1(int32_t curH, int32_t hStart, float& rowSum)
    {
        // DeQue inputs
        goInLocal_ = inQGo_.DeQue<T>();
        normInLocal_ = inQNorm_.DeQue<float>();
        wInLocal_ = inQW_.DeQue<float>();

        // Cast grad_output → f32
        AscendC::LocalTensor<float> goF32;
        if constexpr (std::is_same_v<T, float>) {
            goF32 = goInLocal_.template ReinterpretCast<float>();
        } else {
            goF32 = goCastBuf_.Get<float>();
            AscendC::Cast(goF32, goInLocal_, AscendC::RoundMode::CAST_NONE, curH);
            AscendC::PipeBarrier<PIPE_V>();
        }

        // gn = grad_output_f32 * weight
        AscendC::LocalTensor<float> gn = gnBuf_.Get<float>();
        AscendC::LocalTensor<float> prod = prodBuf_.Get<float>();
        AscendC::Mul(gn, goF32, wInLocal_, curH);

        // --- Accumulate local_grad_weight: += grad_output_f32 * normalized ---
        AscendC::Mul(prod, goF32, normInLocal_, curH);
        {
            AscendC::LocalTensor<float> lwAll = localGWBuf_.Get<float>();
            AscendC::LocalTensor<float> lwTile = lwTileBuf_.Get<float>();
            AscendC::LocalTensor<float> lwAdd = lwAddBuf_.Get<float>();
            // Read current local_g_w tile
            AscendC::DataCopy(lwTile, lwAll[hStart], curH);
            AscendC::PipeBarrier<PIPE_V>();
            // Add product
            AscendC::Add(lwAdd, lwTile, prod, curH);
            // Write back
            AscendC::DataCopy(lwAll[hStart], lwAdd, curH);
            AscendC::PipeBarrier<PIPE_V>();
        }

        // --- Accumulate row_sum: += reduce_sum(gn * norm_f32) ---
        AscendC::Mul(prod, gn, normInLocal_, curH);
        AscendC::LocalTensor<uint8_t> reduceTmp = reduceTmpBuf_.Get<uint8_t>();
        AscendC::LocalTensor<float> rsScalar = rstdBcastBuf_.Get<float>(); // reuse buffer
        AscendC::ReduceSum<float>(rsScalar, prod, reduceTmp, static_cast<uint32_t>(curH));
        AscendC::PipeBarrier<PIPE_ALL>();
        rowSum += rsScalar.GetValue(0);

        // Free input tensors
        inQGo_.FreeTensor(goInLocal_);
        inQNorm_.FreeTensor(normInLocal_);
        inQW_.FreeTensor(wInLocal_);
    }

    // -----------------------------------------------------------------------
    // ComputePass2: grad_x = rstd * (gn - row_mean * norm), cast to output type
    // -----------------------------------------------------------------------
    __aicore__ inline void ComputePass2(int32_t curH, float rowMean, float rstdVal)
    {
        // DeQue inputs
        goInLocal_ = inQGo_.DeQue<T>();
        normInLocal_ = inQNorm_.DeQue<float>();
        wInLocal_ = inQW_.DeQue<float>();

        // Cast grad_output → f32
        AscendC::LocalTensor<float> goF32;
        if constexpr (std::is_same_v<T, float>) {
            goF32 = goInLocal_.template ReinterpretCast<float>();
        } else {
            goF32 = goCastBuf_.Get<float>();
            AscendC::Cast(goF32, goInLocal_, AscendC::RoundMode::CAST_NONE, curH);
            AscendC::PipeBarrier<PIPE_V>();
        }

        // Broadcast row_mean and rstd to tile width
        AscendC::LocalTensor<float> meanBcast = meanBcastBuf_.Get<float>();
        AscendC::LocalTensor<float> rstdBcast = rstdBcastBuf_.Get<float>();
        AscendC::Duplicate(meanBcast, rowMean, curH);
        AscendC::Duplicate(rstdBcast, rstdVal, curH);
        AscendC::PipeBarrier<PIPE_V>();

        // gn = grad_output_f32 * weight
        AscendC::LocalTensor<float> gn = gnBuf_.Get<float>();
        AscendC::Mul(gn, goF32, wInLocal_, curH);

        // grad_x = rstd * (gn - row_mean * norm)
        AscendC::LocalTensor<float> prod = prodBuf_.Get<float>();
        AscendC::LocalTensor<float> gxF32 = gxF32Buf_.Get<float>();

        // Step 1: row_mean * normalized
        AscendC::Mul(prod, meanBcast, normInLocal_, curH);
        // Step 2: gn - (row_mean * norm)
        AscendC::Sub(gxF32, gn, prod, curH);
        // Step 3: rstd * result
        AscendC::Mul(gxF32, gxF32, rstdBcast, curH);

        // Allocate output, cast f32→output type, EnQue for CopyOut
        goOutLocal_ = outQ_.AllocTensor<T>();
        if constexpr (std::is_same_v<T, float>) {
            AscendC::DataCopy(goOutLocal_, gxF32, curH);
        } else {
            AscendC::Cast(goOutLocal_, gxF32, AscendC::RoundMode::CAST_NONE, curH);
            AscendC::PipeBarrier<PIPE_V>();
        }
        outQ_.EnQue(goOutLocal_);

        // Free input tensors
        inQGo_.FreeTensor(goInLocal_);
        inQNorm_.FreeTensor(normInLocal_);
        inQW_.FreeTensor(wInLocal_);
    }

    // -----------------------------------------------------------------------
    // CopyOut: DeQue output, write to both grad_hidden_states and grad_residual
    // -----------------------------------------------------------------------
    __aicore__ inline void CopyOut(int32_t b, int32_t s, int32_t hStart, int32_t curH)
    {
        uint64_t rowOff = static_cast<uint64_t>(b) * S_ * H_ + static_cast<uint64_t>(s) * H_;

        goOutLocal_ = outQ_.DeQue<T>();
        StoreUbToGm(ghsGM_[rowOff + hStart], goOutLocal_, static_cast<uint32_t>(curH));
        StoreUbToGm(gresGM_[rowOff + hStart], goOutLocal_, static_cast<uint32_t>(curH));
        outQ_.FreeTensor(goOutLocal_);
    }

    // -----------------------------------------------------------------------
    // LoadRstd: Read rstd[b, s] scalar from GM
    // -----------------------------------------------------------------------
    __aicore__ inline float LoadRstd(int32_t b, int32_t s)
    {
        AscendC::LocalTensor<float> rBuf = rstdBcastBuf_.Get<float>();
        LoadGmToUb(rBuf, rstdGM_[static_cast<uint64_t>(b) * S_ + s], 1U);
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
        float val = rBuf.GetValue(0);
        return val;
    }

    // -----------------------------------------------------------------------
    // WriteLocalGWToWorkspace: Write per-core local_grad_weight to workspace
    // -----------------------------------------------------------------------
    __aicore__ inline void WriteLocalGWToWorkspace(int32_t coreIdx)
    {
        for (int32_t ht = 0; ht < numHTiles_; ++ht) {
            int32_t hStart = ht * tileH_;
            int32_t curH = (hStart + tileH_ <= H_) ? tileH_ : (H_ - hStart);

            AscendC::LocalTensor<float> lwAll = localGWBuf_.Get<float>();
            AscendC::LocalTensor<float> lwTile = lwTileBuf_.Get<float>();
            AscendC::DataCopy(lwTile, lwAll[hStart], curH);
            AscendC::PipeBarrier<PIPE_V>();
            StoreUbToGm(wsGM_[static_cast<uint64_t>(coreIdx) * H_ + hStart], lwTile,
                        static_cast<uint32_t>(curH));
        }
    }

    // =======================================================================
    // Members
    // =======================================================================
    int32_t B_ = 0, S_ = 0, H_ = 0;
    int32_t totalRows_ = 0, rowsPerCore_ = 0;
    int32_t tileH_ = 0, numHTiles_ = 0;
    int32_t numCores_ = 0;

    // Global tensors
    AscendC::GlobalTensor<T> goGM_;
    AscendC::GlobalTensor<float> xGM_;
    AscendC::GlobalTensor<float> normGM_;
    AscendC::GlobalTensor<float> rstdGM_;
    AscendC::GlobalTensor<float> weightGM_;
    AscendC::GlobalTensor<T> ghsGM_;
    AscendC::GlobalTensor<T> gresGM_;
    AscendC::GlobalTensor<float> wsGM_;

    // Pipe
    AscendC::TPipe pipe;

    // TQue (double-buffered)
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQGo_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQNorm_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQW_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQ_;

    // TBuf
    AscendC::TBuf<AscendC::TPosition::VECCALC> goCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gnBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> prodBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gxF32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> meanBcastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> rstdBcastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceTmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> lwTileBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> lwAddBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> localGWBuf_;

    // Local tensor references
    AscendC::LocalTensor<T> goInLocal_;
    AscendC::LocalTensor<float> normInLocal_;
    AscendC::LocalTensor<float> wInLocal_;
    AscendC::LocalTensor<T> goOutLocal_;
};

// =========================================================================
// Kernel entry point
// dtypeFlag: 1=fp16, 2=bf16
// =========================================================================

extern "C" __global__ __aicore__ void fused_residual_rms_norm_backward(
    GM_ADDR grad_output, GM_ADDR x, GM_ADDR normalized,
    GM_ADDR rstd, GM_ADDR weight,
    GM_ADDR grad_hidden_states, GM_ADDR grad_residual,
    GM_ADDR workspace,
    int32_t B, int32_t S, int32_t H,
    int32_t totalRows, int32_t rowsPerCore,
    int32_t tileH, int32_t numHTiles,
    int32_t numCores,
    int64_t dtypeFlag)
{
    if (dtypeFlag == 1) {
        KernelFusedResidualRmsNormBackward<half> kernel;
        kernel.Init(grad_output, x, normalized, rstd, weight,
                    grad_hidden_states, grad_residual, workspace,
                    B, S, H, totalRows, rowsPerCore, tileH, numHTiles, numCores);
        kernel.Process();
    } else {
        KernelFusedResidualRmsNormBackward<bfloat16_t> kernel;
        kernel.Init(grad_output, x, normalized, rstd, weight,
                    grad_hidden_states, grad_residual, workspace,
                    B, S, H, totalRows, rowsPerCore, tileH, numHTiles, numCores);
        kernel.Process();
    }
}
