#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// ----------- Data movement helpers -----------

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T>& dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    const AscendC::LocalTensor<T>& src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =====================================================================
// Kernel: simplified, closer to proven fused_add_rmsnorm pattern
// =====================================================================

template <typename T>
class KernelFusedResidualRmsNormBackward {
public:
    __aicore__ inline void Init(
        GM_ADDR go, GM_ADDR norm, GM_ADDR rstd, GM_ADDR w,
        GM_ADDR ghs, GM_ADDR gres, GM_ADDR ws,
        int32_t B, int32_t S, int32_t H,
        int32_t totalR, int32_t rpc, int32_t tH, int32_t nHT,
        int32_t nC)
    {
        B_=B; S_=S; H_=H;
        totalRows_=totalR; rowsPerCore_=rpc;
        tileH_=tH; numHTiles_=nHT; numCores_=nC;

        uint64_t bs = static_cast<uint64_t>(B)*S*H;
        goGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(go), bs);
        normGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(norm), bs);
        rstdGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(rstd),
                                static_cast<uint64_t>(B)*S);
        wGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(w), H_);
        ghsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(ghs), bs);
        gresGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(gres), bs);
        wsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(ws),
                              static_cast<uint64_t>(nC)*H_);
        if ASCEND_IS_AIV { InitAiv(); }
    }

    __aicore__ inline void InitAiv()
    {
        pipe.InitBuffer(inQGo_, BUFFER_NUM, tileH_*sizeof(T));
        pipe.InitBuffer(inQNorm_, BUFFER_NUM, tileH_*sizeof(float));
        pipe.InitBuffer(inQW_, BUFFER_NUM, tileH_*sizeof(float));
        pipe.InitBuffer(outQ_, BUFFER_NUM, tileH_*sizeof(T));

        if constexpr (!std::is_same_v<T,float>) {
            pipe.InitBuffer(goCast_, tileH_*sizeof(float));
        }
        pipe.InitBuffer(gn_, tileH_*sizeof(float));
        pipe.InitBuffer(tmp1_, tileH_*sizeof(float));
        pipe.InitBuffer(tmp2_, tileH_*sizeof(float));
        pipe.InitBuffer(tmp3_, tileH_*sizeof(float));
        pipe.InitBuffer(accBuf_, tileH_*sizeof(float));
        pipe.InitBuffer(rdBuf_, tileH_*sizeof(float));
        pipe.InitBuffer(lwT_, tileH_*sizeof(float));
        pipe.InitBuffer(lwA_, tileH_*sizeof(float));
        pipe.InitBuffer(lwAll_, H_*sizeof(float));
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            int32_t rs = ci * rowsPerCore_;
            int32_t re = rs + rowsPerCore_;
            if (re > totalRows_) re = totalRows_;
            int32_t nlr = re - rs;

            // zero local_g_w
            {
                AscendC::LocalTensor<float> lw = lwAll_.Get<float>();
                AscendC::Duplicate(lw, 0.0f, H_);
                AscendC::PipeBarrier<PIPE_V>();
            }

            for (int32_t r = 0; r < nlr; ++r) {
                int32_t ri = rs + r;
                int32_t b = static_cast<int32_t>(
                    static_cast<uint64_t>(ri) / static_cast<uint64_t>(S_));
                int32_t s = ri - b * S_;
                ProcessRow(b, s);
            }

            // write local_g_w → workspace[ci,:]
            for (int32_t ht = 0; ht < numHTiles_; ++ht) {
                int32_t hs = ht * tileH_;
                int32_t cH = (hs + tileH_ <= H_) ? tileH_ : (H_ - hs);
                AscendC::LocalTensor<float> lw = lwAll_.Get<float>();
                AscendC::LocalTensor<float> t = lwT_.Get<float>();
                AscendC::DataCopy(t, lw[hs], cH);
                AscendC::PipeBarrier<PIPE_V>();
                StoreUbToGm(wsGM_[static_cast<uint64_t>(ci)*H_+hs], t,
                            static_cast<uint32_t>(cH));
            }
        }
    }

private:
    __aicore__ inline void ProcessRow(int32_t b, int32_t s)
    {
        // ----- Pass 1: mean + local_g_w -----
        float rowSum = 0.f;
        for (int32_t ht = 0; ht < numHTiles_; ++ht) {
            int32_t hs = ht * tileH_;
            int32_t cH = (hs + tileH_ <= H_) ? tileH_ : (H_ - hs);
            CI(b, s, hs, cH);
            DIQ();
            AscendC::LocalTensor<float> gf = GF(cH);
            AscendC::LocalTensor<float> gn = gn_.Get<float>();
            AscendC::Mul(gn, gf, wL_, cH);
            // grad_w
            {
                AscendC::LocalTensor<float> pr = tmp1_.Get<float>();
                AscendC::Mul(pr, gf, nL_, cH);
                AscendC::LocalTensor<float> lw = lwAll_.Get<float>();
                AscendC::LocalTensor<float> lt = lwT_.Get<float>();
                AscendC::LocalTensor<float> la = lwA_.Get<float>();
                AscendC::DataCopy(lt, lw[hs], cH);
                AscendC::PipeBarrier<PIPE_V>();
                AscendC::Add(la, lt, pr, cH);
                AscendC::DataCopy(lw[hs], la, cH);
                AscendC::PipeBarrier<PIPE_V>();
            }
            // row_sum
            {
                AscendC::LocalTensor<float> pr = tmp1_.Get<float>();
                AscendC::Mul(pr, gn, nL_, cH);
                AscendC::LocalTensor<float> rd = rdBuf_.Get<float>();
                AscendC::LocalTensor<float> sc = tmp3_.Get<float>();
                AscendC::ReduceSum<float>(sc, pr, rd,
                                           static_cast<uint32_t>(cH));
                AscendC::PipeBarrier<PIPE_ALL>();
                rowSum += sc.GetValue(0);
            }
            FIQ();
        }
        float rm = rowSum * (1.f / static_cast<float>(H_));
        float rv = LR(b, s);

        // ----- Pass 2: grad_x + write -----
        for (int32_t ht = 0; ht < numHTiles_; ++ht) {
            int32_t hs = ht * tileH_;
            int32_t cH = (hs + tileH_ <= H_) ? tileH_ : (H_ - hs);
            CI(b, s, hs, cH);
            DIQ();
            AscendC::LocalTensor<float> gf = GF(cH);
            AscendC::LocalTensor<float> gn = gn_.Get<float>();
            AscendC::Mul(gn, gf, wL_, cH);
            AscendC::LocalTensor<float> pr = tmp1_.Get<float>();
            AscendC::LocalTensor<float> gx = tmp2_.Get<float>();
            AscendC::LocalTensor<float> mb = tmp3_.Get<float>();
            AscendC::LocalTensor<float> rb = accBuf_.Get<float>();
            AscendC::Duplicate(mb, rm, cH);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Duplicate(rb, rv, cH);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Mul(pr, mb, nL_, cH);
            AscendC::Sub(gx, gn, pr, cH);
            AscendC::Mul(gx, gx, rb, cH);

            oL_ = outQ_.AllocTensor<T>();
            if constexpr (std::is_same_v<T,float>) {
                AscendC::DataCopy(oL_, gx, cH);
            } else if constexpr (std::is_same_v<T,bfloat16_t>) {
                AscendC::Cast(oL_, gx, AscendC::RoundMode::CAST_ROUND, cH);
                AscendC::PipeBarrier<PIPE_V>();
            } else {
                AscendC::Cast(oL_, gx, AscendC::RoundMode::CAST_NONE, cH);
                AscendC::PipeBarrier<PIPE_V>();
            }
            outQ_.EnQue(oL_);

            FIQ();

            uint64_t ro = static_cast<uint64_t>(b)*S_*H_ + static_cast<uint64_t>(s)*H_;
            oL_ = outQ_.DeQue<T>();
            StoreUbToGm(ghsGM_[ro+hs], oL_, static_cast<uint32_t>(cH));
            StoreUbToGm(gresGM_[ro+hs], oL_, static_cast<uint32_t>(cH));
            outQ_.FreeTensor(oL_);
        }
    }

    // ------- helpers -------
    __aicore__ inline void CI(int32_t b, int32_t s, int32_t hs, int32_t cH)
    {
        uint64_t ro = static_cast<uint64_t>(b)*S_*H_ + static_cast<uint64_t>(s)*H_;
        gL_ = inQGo_.AllocTensor<T>();
        LoadGmToUb(gL_, goGM_[ro+hs], static_cast<uint32_t>(cH));
        inQGo_.EnQue(gL_);
        nL_ = inQNorm_.AllocTensor<float>();
        LoadGmToUb(nL_, normGM_[ro+hs], static_cast<uint32_t>(cH));
        inQNorm_.EnQue(nL_);
        wL_ = inQW_.AllocTensor<float>();
        LoadGmToUb(wL_, wGM_[hs], static_cast<uint32_t>(cH));
        inQW_.EnQue(wL_);
    }

    __aicore__ inline void DIQ()
    {
        gL_ = inQGo_.DeQue<T>();
        nL_ = inQNorm_.DeQue<float>();
        wL_ = inQW_.DeQue<float>();
    }

    __aicore__ inline AscendC::LocalTensor<float> GF(int32_t cH)
    {
        AscendC::LocalTensor<float> f;
        if constexpr (std::is_same_v<T,float>) {
            f = gL_.template ReinterpretCast<float>();
        } else {
            f = goCast_.Get<float>();
            AscendC::Cast(f, gL_, AscendC::RoundMode::CAST_NONE, cH);
            AscendC::PipeBarrier<PIPE_V>();
        }
        return f;
    }

    __aicore__ inline void FIQ()
    {
        inQGo_.FreeTensor(gL_);
        inQNorm_.FreeTensor(nL_);
        inQW_.FreeTensor(wL_);
    }

    __aicore__ inline float LR(int32_t b, int32_t s)
    {
        AscendC::LocalTensor<float> rb = gn_.Get<float>();
        LoadGmToUb(rb, rstdGM_[static_cast<uint64_t>(b)*S_+s], 1U);
        AscendC::PipeBarrier<PIPE_MTE2>();
        AscendC::PipeBarrier<PIPE_ALL>();
        return rb.GetValue(0);
    }

    int32_t B_=0,S_=0,H_=0,totalRows_=0,rowsPerCore_=0,tileH_=0,numHTiles_=0,numCores_=0;
    AscendC::GlobalTensor<T> goGM_,ghsGM_,gresGM_;
    AscendC::GlobalTensor<float> normGM_,rstdGM_,wGM_,wsGM_;
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN,BUFFER_NUM> inQGo_,inQNorm_,inQW_;
    AscendC::TQue<AscendC::TPosition::VECOUT,BUFFER_NUM> outQ_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> goCast_,gn_,tmp1_,tmp2_,tmp3_,accBuf_,rdBuf_,lwT_,lwA_,lwAll_;
    AscendC::LocalTensor<T> gL_,oL_;
    AscendC::LocalTensor<float> nL_,wL_;
};

extern "C" __global__ __aicore__ void fused_residual_rms_norm_backward(
    GM_ADDR go, GM_ADDR norm, GM_ADDR rstd, GM_ADDR w,
    GM_ADDR ghs, GM_ADDR gres, GM_ADDR ws,
    int32_t B, int32_t S, int32_t H,
    int32_t tr, int32_t rpc, int32_t tH, int32_t nHT, int32_t nC, int64_t dF)
{
    if (dF == 1) {
        KernelFusedResidualRmsNormBackward<half> k;
        k.Init(go, norm, rstd, w, ghs, gres, ws, B, S, H, tr, rpc, tH, nHT, nC);
        k.Process();
    } else {
        KernelFusedResidualRmsNormBackward<bfloat16_t> k;
        k.Init(go, norm, rstd, w, ghs, gres, ws, B, S, H, tr, rpc, tH, nHT, nC);
        k.Process();
    }
}
