7	//
8	// The kernel computes per-row grad_hidden_states, grad_residual,
9	// and per-core partial grad_weight sums (stored in workspace).
10	// Host reduces workspace across cores to get final grad_weight.
11	
12	#include <algorithm>
13	#include <cstdint>
14	
15	#include <torch/extension.h>
