22	
23	constexpr int32_t DEFAULT_TILE_H = 256;
24	constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
25	
26	namespace ascend_kernel {
27	
28	std::tuple<at::Tensor, at::Tensor, at::Tensor> fused_residual_rms_norm_backward(
29	    const at::Tensor& grad_output,
30	    const at::Tensor& x,
31	    const at::Tensor& normalized,
32	    const at::Tensor& rstd,
33	    const at::Tensor& weight)
34	{
35	    TORCH_CHECK(grad_output.dim() == 3, "grad_output must be [B, S, H]");
36	    TORCH_CHECK(grad_output.scalar_type() == at::kBFloat16 || grad_output.scalar_type() == at::kHalf,
37	                "grad_output must be bfloat16 or float16");
38	    TORCH_CHECK(grad_output.is_contiguous(), "grad_output must be contiguous");
39	
40	    int32_t B = static_cast<int32_t>(grad_output.sizes()[0]);
41	    int32_t S = static_cast<int32_t>(grad_output.sizes()[1]);
42	    int32_t H = static_cast<int32_t>(grad_output.sizes()[2]);
43	
44	    TORCH_CHECK(static_cast<int32_t>(rstd.sizes()[2]) == 1, "rstd last dim must be 1");
45	    TORCH_CHECK(static_cast<int32_t>(weight.sizes()[0]) == H, "weight shape mismatch");
46	
47	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
48	    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
49	    int32_t numCores = static_cast<int32_t>(std::min<int64_t>(DEFAULT_NUM_PHYSICAL_CORES,
50	                                                               std::max<int64_t>(1, coreNum)));
51	
52	    int32_t totalRows = B * S;
53	    int32_t rowsPerCore = (totalRows + numCores - 1) / numCores;
54	    int32_t tileH = DEFAULT_TILE_H;
55	    int32_t numHTiles = (H + tileH - 1) / tileH;
56	
57	    int64_t dtypeFlag = (grad_output.scalar_type() == at::kHalf) ? 1 : 2;
58	
59	    // Output tensors
60	    auto grad_hs = at::empty({B, S, H}, grad_output.options());
61	    auto grad_res = at::empty({B, S, H}, grad_output.options());
62	
63	    // Workspace for per-core partial grad_weight
64	    auto workspace = at::zeros({numCores, H}, at::TensorOptions().dtype(at::kFloat).device(grad_output.device()));
65	
66	    uint32_t blockDim = static_cast<uint32_t>(numCores);
67	
68	    EXEC_KERNEL_CMD(fused_residual_rms_norm_backward, blockDim,
69	                    grad_output, normalized, rstd, weight,
70	                    grad_hs, grad_res, workspace,
71	                    B, S, H, totalRows, rowsPerCore, tileH, numHTiles, numCores,
72	                    dtypeFlag);
73	
74	    // Reduce workspace across cores → grad_weight
75	    auto grad_w = at::sum(workspace, 0, false);
76	
77	    return std::make_tuple(grad_hs, grad_res, grad_w);
78	}
