#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T>& dst, AscendC::GlobalTensor<T> src, uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count*static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, cp, pp);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst, const AscendC::LocalTensor<T>& src, uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count*static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, cp);
}

template <typename T>
class KernelFusedResidualRmsNormBackward {
public:
    __aicore__ inline void Init(
        GM_ADDR go, GM_ADDR norm, GM_ADDR rstd, GM_ADDR w,
        GM_ADDR ghs, GM_ADDR gres,
        int32_t B, int32_t S, int32_t H,
        int32_t tr, int32_t r, int32_t tH, int32_t nHT)
    {
        B_=B;S_=S;H_=H;totalRows_=tr;rowsPerCore_=r;tileH_=tH;numHTiles_=nHT;
        uint64_t bs=static_cast<uint64_t>(B)*S*H;
        goGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(go),bs);
        normGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(norm),bs);
        rstdGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(rstd),static_cast<uint64_t>(B)*S);
        wGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(w),H_);
        ghsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(ghs),bs);
        gresGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(gres),bs);
        if ASCEND_IS_AIV{InitAiv();}
    }

    __aicore__ inline void InitAiv()
    {
        pipe.InitBuffer(iQGo_,BUFFER_NUM,tileH_*sizeof(T));
        pipe.InitBuffer(iQN_,BUFFER_NUM,tileH_*sizeof(float));
        pipe.InitBuffer(iQW_,BUFFER_NUM,tileH_*sizeof(float));
        pipe.InitBuffer(oQ_,BUFFER_NUM,tileH_*sizeof(T));
        if constexpr(!std::is_same_v<T,float>){pipe.InitBuffer(gc_,tileH_*sizeof(float));}
        pipe.InitBuffer(gn_,tileH_*sizeof(float));
        pipe.InitBuffer(t1_,tileH_*sizeof(float));
        pipe.InitBuffer(t2_,tileH_*sizeof(float));
        pipe.InitBuffer(t3_,tileH_*sizeof(float));
        pipe.InitBuffer(rd_,tileH_*sizeof(float));
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV{
            int32_t ci=AscendC::GetBlockIdx()/AscendC::GetSubBlockNum();
            int32_t rs=ci*rowsPerCore_;
            int32_t re=rs+rowsPerCore_;
            if(re>totalRows_)re=totalRows_;
            for(int32_t ri=rs;ri<re;++ri){
                int32_t b=static_cast<int32_t>(static_cast<uint64_t>(ri)/static_cast<uint64_t>(S_));
                int32_t s=ri-b*S_;
                ProcessRow(b,s);
            }
        }
    }

private:
    __aicore__ inline void ProcessRow(int32_t b, int32_t s)
    {
        // Pass 1: row_mean
        float rsum=0.f;
        for(int32_t ht=0;ht<numHTiles_;++ht){
            int32_t hs=ht*tileH_;
            int32_t cH=(hs+tileH_<=H_)?tileH_:(H_-hs);
            CI(b,s,hs,cH);DIQ();
            AscendC::LocalTensor<float> gf=GF(cH);
            AscendC::LocalTensor<float> gn=gn_.Get<float>();
            AscendC::Mul(gn,gf,wL_,cH);
            AscendC::LocalTensor<float> p=t1_.Get<float>();
            AscendC::Mul(p,gn,nL_,cH);
            AscendC::LocalTensor<float> rd=rd_.Get<float>();
            AscendC::LocalTensor<float> sc=t3_.Get<float>();
            AscendC::ReduceSum<float>(sc,p,rd,static_cast<uint32_t>(cH));
            AscendC::PipeBarrier<PIPE_ALL>();
            rsum+=sc.GetValue(0);
            FIQ();
        }
        float rm=rsum*(1.f/static_cast<float>(H_));
        float rv=LR(b,s);

        // Pass 2: grad_x + write
        for(int32_t ht=0;ht<numHTiles_;++ht){
            int32_t hs=ht*tileH_;
            int32_t cH=(hs+tileH_<=H_)?tileH_:(H_-hs);
            CI(b,s,hs,cH);DIQ();
            AscendC::LocalTensor<float> gf=GF(cH);
            AscendC::LocalTensor<float> gn=gn_.Get<float>();
            AscendC::Mul(gn,gf,wL_,cH);
            AscendC::LocalTensor<float> p=t1_.Get<float>();
            AscendC::LocalTensor<float> gx=t2_.Get<float>();
            AscendC::LocalTensor<float> mb=t3_.Get<float>();
            AscendC::Duplicate(mb,rm,cH);AscendC::PipeBarrier<PIPE_V>();
            AscendC::Duplicate(gx,rv,cH);AscendC::PipeBarrier<PIPE_V>();
            AscendC::Mul(p,mb,nL_,cH);
            AscendC::Sub(gx,gn,p,cH);
            AscendC::Mul(gx,gx,gx,cH);
            // gx now = rstd * (gn - row_mean*norm), but wait - I overwrote with Mul(gx,gx,gx,cH)
            // Fix: need separate rstd version
            AscendC::LocalTensor<float> rb=gn_.Get<float>();
            AscendC::Duplicate(rb,rv,cH);AscendC::PipeBarrier<PIPE_V>();
            AscendC::Mul(gx,gx,rb,cH);

            oL_=oQ_.AllocTensor<T>();
            if constexpr(std::is_same_v<T,bfloat16_t>){
                AscendC::Cast(oL_,gx,AscendC::RoundMode::CAST_ROUND,cH);AscendC::PipeBarrier<PIPE_V>();
            }else if constexpr(!std::is_same_v<T,float>){
                AscendC::Cast(oL_,gx,AscendC::RoundMode::CAST_NONE,cH);AscendC::PipeBarrier<PIPE_V>();
            }else{AscendC::DataCopy(oL_,gx,cH);}
            oQ_.EnQue(oL_);
            FIQ();

            uint64_t ro=static_cast<uint64_t>(b)*S_*H_+static_cast<uint64_t>(s)*H_;
            oL_=oQ_.DeQue<T>();
            StoreUbToGm(ghsGM_[ro+hs],oL_,static_cast<uint32_t>(cH));
            StoreUbToGm(gresGM_[ro+hs],oL_,static_cast<uint32_t>(cH));
            oQ_.FreeTensor(oL_);
        }
    }

    __aicore__ inline void CI(int32_t b,int32_t s,int32_t hs,int32_t cH){
        uint64_t ro=static_cast<uint64_t>(b)*S_*H_+static_cast<uint64_t>(s)*H_;
        gL_=iQGo_.AllocTensor<T>();LoadGmToUb(gL_,goGM_[ro+hs],static_cast<uint32_t>(cH));iQGo_.EnQue(gL_);
        nL_=iQN_.AllocTensor<float>();LoadGmToUb(nL_,normGM_[ro+hs],static_cast<uint32_t>(cH));iQN_.EnQue(nL_);
        wL_=iQW_.AllocTensor<float>();LoadGmToUb(wL_,wGM_[hs],static_cast<uint32_t>(cH));iQW_.EnQue(wL_);
    }
    __aicore__ inline void DIQ(){gL_=iQGo_.DeQue<T>();nL_=iQN_.DeQue<float>();wL_=iQW_.DeQue<float>();}
    __aicore__ inline AscendC::LocalTensor<float> GF(int32_t cH){
        AscendC::LocalTensor<float> f;
        if constexpr(std::is_same_v<T,float>){f=gL_.template ReinterpretCast<float>();}
        else{f=gc_.Get<float>();AscendC::Cast(f,gL_,AscendC::RoundMode::CAST_NONE,cH);AscendC::PipeBarrier<PIPE_V>();}
        return f;
    }
    __aicore__ inline void FIQ(){iQGo_.FreeTensor(gL_);iQN_.FreeTensor(nL_);iQW_.FreeTensor(wL_);}
    __aicore__ inline float LR(int32_t b,int32_t s){
        AscendC::LocalTensor<float> rb=gn_.Get<float>();
        LoadGmToUb(rb,rstdGM_[static_cast<uint64_t>(b)*S_+s],1U);
        AscendC::PipeBarrier<PIPE_MTE2>();AscendC::PipeBarrier<PIPE_ALL>();
        return rb.GetValue(0);
    }

    int32_t B_=0,S_=0,H_=0,totalRows_=0,rowsPerCore_=0,tileH_=0,numHTiles_=0;
    AscendC::GlobalTensor<T> goGM_,ghsGM_,gresGM_;
    AscendC::GlobalTensor<float> normGM_,rstdGM_,wGM_;
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN,BUFFER_NUM> iQGo_,iQN_,iQW_;
    AscendC::TQue<AscendC::TPosition::VECOUT,BUFFER_NUM> oQ_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gc_,gn_,t1_,t2_,t3_,rd_;
    AscendC::LocalTensor<T> gL_,oL_;
    AscendC::LocalTensor<float> nL_,wL_;
};

extern "C" __global__ __aicore__ void fused_residual_rms_norm_backward(
    GM_ADDR go, GM_ADDR norm, GM_ADDR rstd, GM_ADDR w,
